exercises.starter:
def first_own_frame(traceback_text, project_dir):
    for line in traceback_text.splitlines():
        if project_dir in line:
            return line

tests.code:
try:
    row_count_bounds({"contract_id": "nat_v2", "row_count_min": 1})
except ValueError as err:
    assert isinstance(err.__cause__, KeyError), "not chained with from"
    assert "nat_v2" in str(err) and "row_count_max" in str(err), str(err)
else:
    raise AssertionError("no ValueError")

try:
    row_count_bounds(None)
except TypeError:
    pass
else:
    raise AssertionError("TypeError was swallowed")

exercises.starter:
def row_count_bounds(contract):
    try:
        return contract["row_count_min"], contract["row_count_max"]
    except Exception:
        raise ValueError("bad contract")
